#[derive(Clone, Copy)]
struct Point {
    x: i32,
    y: i32,
}

fn main() {
    let on_stack = Point { x: 1, y: 2 };  // a stack slot, as in C
    let mut on_heap = Box::new(on_stack); // heap memory with one owner
    on_heap.x = 10;
    let alias = &on_heap;                 // a borrow the compiler tracks
    println!("{} {} {} {}", on_stack.x, alias.x, alias.y, size_of::<Point>());
}                                         // the Box is freed here, exactly once

