#include <stdio.h>
#include <stdlib.h>

struct point { int x, y; };

int main(void) {
    struct point on_stack = {1, 2};                    /* a stack slot */
    struct point *on_heap = malloc(sizeof *on_heap);   /* heap, freed by hand */
    if (!on_heap) return 1;
    *on_heap = on_stack;
    on_heap->x = 10;
    struct point *alias = on_heap;                     /* any pointer may alias */
    printf("%d %d %d %zu\n", on_stack.x, alias->x, alias->y, sizeof(struct point));
    free(on_heap);
    /* alias still holds the address; nothing stops a later *alias. */
    return 0;
}
